/* Several firmware functions carry the names of C library functions (strcat, strchr,
 * memcpy...). They are the firmware's OWN implementations, recovered at real addresses
 * in flash, and their recovered signatures do not always match the host C library's.
 * That is a fact about this firmware, not an error, so the host's builtin declarations
 * are suppressed rather than the recovered signatures being bent to match them. */
#if defined(__clang__)
#pragma GCC diagnostic ignored "-Wincompatible-library-redeclaration"
#elif defined(__GNUC__)
#pragma GCC diagnostic ignored "-Wbuiltin-declaration-mismatch"
#endif

